// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, uint256 warpTime, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(warpTime > block.timestamp);
        vm.warp(warpTime);
        vm.assume(amount < 10 ether || amount > 10 ether); // any value other than exactly 10 ether
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(!(ok && amount != 10 ether));
    }
}
